#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "fault_alloc.h"
#include "rbtree.h"

static int g_checks_run    = 0;
static int g_checks_failed = 0;

#define RB_CHECK(cond)                                                        \
    do {                                                                      \
        g_checks_run++;                                                       \
        if (!(cond)) {                                                        \
            g_checks_failed++;                                                \
            fprintf(stderr, "  FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
        }                                                                     \
    } while (0)

/* Marks (rather than frees) so ownership tests can inspect .freed after the
 * fact without a use-after-free; backed by a static array, never heap. */
typedef struct { int freed; } tracked_val_t;

#define MAX_TRACKED 256
static tracked_val_t g_tracked[MAX_TRACKED];
static int g_tracked_count = 0;

static tracked_val_t *tracked_new(void) {
    tracked_val_t *v = &g_tracked[g_tracked_count++];
    v->freed = 0;
    return v;
}

static void tracked_free(void *v) {
    ((tracked_val_t *)v)->freed = 1;
}

static void tracked_reset(void) {
    g_tracked_count = 0;
}

/* Fisher-Yates over rand(); main() seeds once with srand(1) so the sequence
 * (and thus which delete-fixup branches get exercised) is reproducible. */
static void shuffled_ids(int *out, int n) {
    for (int i = 0; i < n; i++) {
        out[i] = i;
    }
    for (int i = n - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        int tmp = out[i];
        out[i] = out[j];
        out[j] = tmp;
    }
}

typedef struct {
    const char *keys[64];
    int count;
} foreach_ctx_t;

static void collect_visit(const char *key, void *value, void *ctx) {
    (void)value;
    foreach_ctx_t *c = ctx;
    c->keys[c->count++] = key;
}

