#include <stdlib.h>

#include "rbtree.h"

/* Internal node/tree layout. NIL is represented by plain NULL (treated as
 * black wherever color is read), not a shared sentinel node. Nodes carry
 * an explicit parent pointer. */

typedef enum { RB_RED, RB_BLACK } rb_color_t;

typedef struct rb_node {
    char           *key;    /* owned copy */
    void           *value;  /* owned iff value_free != NULL, per contract */
    rb_color_t      color;
    struct rb_node *parent; /* NULL at root */
    struct rb_node *left;
    struct rb_node *right;
} rb_node_t;

struct rbtree {
    rb_node_t        *root; /* NULL = empty tree */
    size_t             size;
    rb_value_free_fn   value_free;
};

/* Stub implementations below are scaffolding so the header's contract
 * links and the demo driver compiles/runs. Each remaining body is a safe
 * placeholder to be replaced one function at a time (see CLAUDE.md:
 * "implement in small slices"). */

rbtree_t *rb_create(rb_value_free_fn value_free) {
    rbtree_t *t = malloc(sizeof(*t));
    if (t == NULL) {
        return NULL;
    }
    t->root = NULL;
    t->size = 0;
    t->value_free = value_free;
    return t;
}

int rb_insert(rbtree_t *t, const char *key, void *value) {
    (void)t;
    (void)key;
    (void)value;
    /* TODO(M1): BST insert + red-black fixup. */
    return -1;
}

void *rb_find(const rbtree_t *t, const char *key) {
    (void)t;
    (void)key;
    /* TODO(M1): BST search by strcmp order. */
    return NULL;
}

int rb_delete(rbtree_t *t, const char *key) {
    (void)t;
    (void)key;
    /* TODO(M2): delete + fixup. */
    return -1;
}

size_t rb_size(const rbtree_t *t) {
    (void)t;
    /* TODO(M1): return tracked node count. */
    return 0;
}

void rb_foreach(const rbtree_t *t,
                void (*fn)(const char *key, void *value, void *ctx),
                void *ctx) {
    (void)t;
    (void)fn;
    (void)ctx;
    /* TODO(M1): in-order traversal calling fn(key, value, ctx). */
}

int rb_validate(const rbtree_t *t) {
    (void)t;
    /* TODO(M1): check the red-black invariants listed in rbtree.h. */
    return 0;
}

void rb_destroy(rbtree_t *t) {
    (void)t;
    /* TODO(M1): free all nodes, key copies, and owned values. NULL-safe. */
}

